
    CREATE TABLE users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ci TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')), password TEXT NOT NULL, must_change INTEGER NOT NULL DEFAULT 1, blocked INTEGER NOT NULL DEFAULT 0);
    CREATE TABLE careers (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT UNIQUE NOT NULL);
    CREATE TABLE shifts (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT UNIQUE NOT NULL);
    CREATE TABLE years (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT UNIQUE NOT NULL);
    CREATE TABLE subjects (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, career_id INTEGER NOT NULL REFERENCES careers(id), level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 3));
    CREATE TABLE modules (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, year_id INTEGER NOT NULL REFERENCES years(id), start_date DATE NOT NULL, end_date DATE NOT NULL, CHECK(start_date<=end_date), UNIQUE(name,year_id));
    CREATE TABLE students (user_id INTEGER PRIMARY KEY REFERENCES users(id), career_id INTEGER NOT NULL REFERENCES careers(id), shift_id INTEGER NOT NULL REFERENCES shifts(id), admission_year_id INTEGER NOT NULL REFERENCES years(id), level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 3));
    CREATE TABLE offerings (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subject_id INTEGER NOT NULL REFERENCES subjects(id), module_id INTEGER NOT NULL REFERENCES modules(id), shift_id INTEGER NOT NULL REFERENCES shifts(id), teacher_id INTEGER NOT NULL REFERENCES users(id), unlocked_until TIMESTAMPTZ, UNIQUE(subject_id,module_id,shift_id));
    CREATE TABLE enrollments (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(user_id), offering_id INTEGER NOT NULL REFERENCES offerings(id), grade DOUBLE PRECISION CHECK(grade BETWEEN 1 AND 100), updated_at TIMESTAMPTZ, saber DOUBLE PRECISION CHECK(saber BETWEEN 0 AND 100), hacer DOUBLE PRECISION CHECK(hacer BETWEEN 0 AND 100), ser DOUBLE PRECISION CHECK(ser BETWEEN 0 AND 100), UNIQUE(student_id,offering_id));
    CREATE TABLE audit (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, detail TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires BIGINT NOT NULL);
  
CREATE INDEX subjects_career_idx ON subjects(career_id,level);
CREATE INDEX modules_year_idx ON modules(year_id,start_date,end_date);
CREATE INDEX offerings_teacher_idx ON offerings(teacher_id,module_id);
CREATE INDEX offerings_module_idx ON offerings(module_id);
CREATE INDEX offerings_shift_idx ON offerings(shift_id);
CREATE INDEX enrollments_offering_idx ON enrollments(offering_id,student_id);
CREATE INDEX students_career_shift_idx ON students(career_id,shift_id);
CREATE INDEX students_admission_idx ON students(admission_year_id);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX sessions_expires_idx ON sessions(expires);
CREATE INDEX audit_actor_idx ON audit(actor_id);
